wire [1:0] gun_mode = 2'b00; // OSD gun stripped; force dead
wire       gun_btn_mode = status[42];

wire cart_download = ioctl_download & (ioctl_index[4:0] == 1 || ioctl_index[4:0] == 2);
// 0.3.0: the Little-Man firmware file. ioctl index 0x40, and the OSD row "Load Little-Man Firmware"
// (F4, index 0x04) for a reload after a refusal, both take the same path. Paprium.mgl uses index 0x04.
// Neither collides with cart_download (index[4:0] 1 / 2) nor with
// tmss_download (index 0, boot0.rom) or code_download (0xFF). The words go through cartridge.sv's fw_dl path
// (SDRAM byte 0x0100_0000), never through cart_dl (which would clear rom_sz / quirks and parse a header).
wire fw_download   = ioctl_download & ((ioctl_index == 8'h40) | (ioctl_index == 8'h04));
wire cart_dl_wait;
wire ioctl_wait = cart_dl_wait; // cart ROM and firmware loads share cartridge.sv's port-0 handshake
wire code_download = ioctl_download & &ioctl_index;
wire tmss_download = ioctl_download & !ioctl_index;

// FXSMS1: SMS mode removed. cart_ms register + ioctl_index==2 SMS mode switch deleted; core is always in Mega Drive (M3=1) mode.

reg osd_btn = 0;
always @(posedge clk_sys) begin
	integer timeout = 0;
	reg     has_bootrom = 0;
	reg     last_rst = 0;

	if (RESET) last_rst <= 0;
	if (status[0]) last_rst <= 1;

	if (cart_download & ioctl_wr & status[0]) has_bootrom <= 1;

	if(last_rst & ~status[0]) begin
		osd_btn <= 0;
		if(timeout < 24000000) begin
			timeout <= timeout + 1;
			osd_btn <= ~has_bootrom;
		end
	end
end

///////////////////////////////////////////////////

// OSD Reset (status[0]) is the full reset, the power switch. PASS9 (B Jam 2026-11-10): the 68000-only Console Reset
// (OSD R[91] + USER button, with its pass 6 watchdog) is removed; the USER button (buttons[1]) now gives the same
// full Reset as the OSD row, as in the stock MiSTer Genesis core.
wire reset   = status[0] | buttons[1] | region_set_rst;
wire loading = cart_download | fw_download | bk_loading | RESET;

// FXALIGN1P ITEM 1' (FX68K-only power-on hold, Pocket 0.2.2 core_top.sv:709 dataslot_allcomplete
// equivalent). Sticky on clk_sys, set when the first cart download ends. Goes ONLY to the FX68K
// wrap via md_board.fx_cart_loaded (2-flop sync inside the wrap). NOT in `loading`: md_reset and
// the VDP/board are not held (that was FXALIGN123's no-video FAIL).
reg fx_cart_loaded = 1'b0;
wire        m68k_pwrUp;                 // PASS6: from FX68K wrap (clk_md domain)
reg         cpu_cold_done = 1'b0;      // PASS6: sticky ~pwrUp on clk_sys for cartridge
reg fx_cdl_fall = 1'b0;   // RSTFIX: one clk_sys pulse at the end of each cart download
always @(posedge clk_sys) begin
	reg old_cart_dl = 1'b0;
	reg pwr_s1 = 1'b1, pwr_s2 = 1'b1;
	old_cart_dl <= cart_download;
	if(old_cart_dl & ~cart_download) fx_cart_loaded <= 1'b1;
	fx_cdl_fall <= old_cart_dl & ~cart_download;   // RSTFIX
	// PASS6: 2-flop sync of m68k_pwrUp into clk_sys; sticky done once cold ends
	pwr_s1 <= m68k_pwrUp;
	pwr_s2 <= pwr_s1;
	if (~pwr_s2) cpu_cold_done <= 1'b1;
end

reg        btn_reset;
reg        md_reset;
reg        s_reset;
wire       paprium_active;
wire       paprium_md_reset;
// FXTIM1: the Paprium MCU reset term (paprium_active & paprium_md_reset) is now registered on clk_md (107 MHz),
// so the Paprium reset arrives at md_board.ext_reset ONE 107 MHz cycle LATER than before (md_reset itself is unchanged).
// Intent: the clk_sys-launched paprium_quirk / fpgio ctrl[0] terms feed only this flop instead of the ym6045 ZV LUT (md_reset_effective -> ext_reset -> SRES).
// paprium_rst_q has an initial value of 1'b1 (power-up at 1, no async reset); with paprium_active=0 it clears on the first clk_md edge.
// UNCHECKED: whether the Paprium cart MCU rewrites ctrl[0] (fpgio.sv:33/43) on a Paprium re-load. The other uses of paprium_active are unchanged.
reg        paprium_rst_q = 1'b1;
// RSTFIX (from the Pocket Little-Man 1.0 reset envelope):
// md_reset_eff = md_reset | (paprium_active & (paprium_md_reset | shell_reset)), shell_reset = cnt < 3.
// Without this, the 68000 can run the boot view's $A5A5 vectors before GO, double-fault and halt for good.
// Three Paprium-only terms are added to the 68000's ext_reset:
//  - pap_pre_go: from the end of a firmware load (ioctl 0x40 or 0x04) until GO (fw_done), whatever paprium_active / HOLD say.
//    Cleared by a later non-Paprium ROM load, so other games never see it.
//  - the Pocket's shell_reset term (s_reset_nx here, = cnt < 3) beside HOLD, as core_top.sv:1267.
//  - pap_rel: a 2^17 clk_md (~1.2 ms) ext_reset pulse when the Paprium hold falls, so the 68000 restarts cleanly
//    and re-reads SSP/PC from the game view. md_reset itself (the RAM clears) is unchanged.
wire       md_reset_effective = md_reset | paprium_rst_q;
// TC030: registered copy for md_board ext_reset / tmss_reset only (paprium_rst_q -> ym7101 slatch missed 107 MHz).
// One clk_md (9.3 ns) later on both edges of a >=1.2 ms pulse; internal users of md_reset_effective unchanged.
reg        md_reset_board_q = 1'b1;
always @(posedge clk_md) md_reset_board_q <= md_reset_effective;
reg [15:1] ram_rst_a;
reg  [4:0] cnt_q = 5'd0;
wire [4:0] paprium_cnt = cnt_q;   // RSTFIX: the envelope counter (one clk_md late), read by pap_hold_nx above
always @(posedge clk_md) begin
	reg [4:0] cnt = 0;
	reg old_reset = 0;
	
	ram_rst_a <= ram_rst_a + 1'd1;
	if(&ram_rst_a & ~&cnt) cnt <= cnt + 1'd1;

	old_reset <= reset;
	if(loading | (~old_reset & reset) | fw_go_md) cnt <= 0;   // 0.3.0: the stub's GO restarts the envelope once

	s_reset <= (cnt < 3);
	cnt_q   <= cnt;
	
	if(loading)       md_reset <= 1;
	else if(cnt == 3) md_reset <= 0;

	if(~old_reset & reset) btn_reset <= 1;
	else if(&cnt)          btn_reset <= 0;
end

reg sys_reset;
reg [1:0] sreset;
always @(posedge clk_sys) begin
	sreset <= {sreset[0], s_reset};
	if(!sreset) sys_reset <= 0;
	if(&sreset) sys_reset <= 1;
end

// 0.3.0 (the Pocket's core_top.sv reset envelope, adapted for MiSTer):
// while the boot stub runs (from the first sys_reset release after a load until GO) paprium_cart's reset ignores
// sys_reset (OSD Reset, region change: the copy cannot be cut); a new load (firmware, ROM, save, the framework's RESET:
// MiSTer's `loading`, T3) still resets it and the stub runs again. From the clock after GO the cart is held until the
// envelope's own sys_reset is up (fw_done, a power-on flag: the boot view closes), so the MCU runs nothing between GO
// and the restart. Elsewhere pap_reset equals sys_reset on every clock. XLINK's od_reset stays sys_reset.
wire       fw_go;                       // cartridge.sv (paprium_cart), clk_sys, power-on flag
wire       fw_len_bad;                  // cartridge.sv length mark -> XLINK FAFRIUM bit 0
wire       fw_go_md;
synch_3 fw_go_sync (.i(fw_go), .o(), .rise(fw_go_md), .clk(clk_md));

reg        fw_stub   = 1'b0;
reg        fw_done   = 1'b0;
reg        pap_reset = 1'b0;
wire       sys_reset_nx = (&sreset) ? 1'b1 : (sreset == 2'b00) ? 1'b0 : sys_reset;
wire       fw_stub_nx   = ~fw_go & ~loading & (fw_stub | ~sys_reset);
always @(posedge clk_sys) begin
	fw_stub   <= fw_stub_nx;
	if (fw_go & sys_reset) fw_done <= 1'b1;
	// Hold the cart (so the stub cannot run or reach GO) until the first cart ROM download has ended
	// (fx_cart_loaded, sticky). The firmware may arrive before the ROM (ioctl 0x40 or the mgl's 0x04).
	// From then on unchanged, so an F4 (0x04) reload reruns the stub as before.
	pap_reset <= (sys_reset_nx & ~fw_stub_nx) | (fw_go & ~fw_done) | ~fx_cart_loaded;
end

// RSTFIX: Paprium 68000 hold terms (see the comment at paprium_rst_q)
reg        pap_fw_seen = 1'b0;   // clk_sys
always @(posedge clk_sys) begin
	reg       old_fw_dl = 1'b0;
	reg [4:0] cdl_end   = 5'd0;
	old_fw_dl <= fw_download;
	cdl_end   <= {cdl_end[3:0], fx_cdl_fall};
	if (old_fw_dl & ~fw_download)        pap_fw_seen <= 1'b1;
	else if (cdl_end[4] & ~paprium_active) pap_fw_seen <= 1'b0;   // a non-Paprium ROM was loaded after the firmware
end
reg  [1:0] pap_pre_go_s = 2'b00;
reg        pap_hold_q   = 1'b0;
reg [16:0] pap_rel      = 17'd0;
wire       s_reset_nx   = (paprium_cnt < 3);
wire       pap_hold_nx  = (paprium_active & (paprium_md_reset | s_reset_nx)) | pap_pre_go_s[1];
always @(posedge clk_md) begin
	pap_pre_go_s <= {pap_pre_go_s[0], pap_fw_seen & ~fw_done};
	pap_hold_q   <= pap_hold_nx;
	if (pap_hold_q & ~pap_hold_nx) pap_rel <= 17'h1FFFF;
	else if (pap_rel != 17'd0)     pap_rel <= pap_rel - 1'd1;
	paprium_rst_q <= pap_hold_nx | (pap_hold_q & ~pap_hold_nx) | (pap_rel != 17'd0);   // no 1-clock gap at the hand-off
end

// PASS9: the Console Reset block (cr_req/cr_btn/cr_hold/CAUSE.V post and the pass 6 cr_wd watchdog) is removed.

reg vclk_en, zclk_en, clk_en;
always @(posedge clk_md) begin
	reg old_vclk, old_zclk;
	
	clk_en <= ~cart_download;
	
	old_vclk <= VCLK;
	if(old_vclk & ~VCLK) vclk_en <= clk_en;

	old_zclk <= ZCLK;
	if(old_zclk & ~ZCLK) zclk_en <= clk_en;
end

always @(posedge clk_md) begin
	reg pause_req;

	pause_req <= OSD_STATUS & status[61];

	if(pause_req & ~md_reset & ~btn_reset & ~cart_download) begin
		dma_z80_req <= 1;
		if((dma_z80_ack | res_z80) & ~cart_dma) dma_68k_req <= 1;
	end
	else begin
		dma_68k_req <= 0;
		dma_z80_req <= 0;
	end
end

///////////////////////////////////////////////////

