// The stock core uses the VDP's early DMA OE to hide SDRAM latency for ordinary
// ROM reads. Paprium's 0xC000-0xFFFF window is not an ordinary ROM read: each
// accepted read advances the cart FPGA's private stream pointer. Use the real
// cartridge OE/CAS0 for Paprium so speculative/early DMA phases cannot consume
// stream words.
wire        cart_oe = paprium_active ? cart_oe_raw : cart_oe_early;


// Muxed cart signals: MD+ overlay takes priority when active
// ---- 0.2.6: 32X / Mega CD detection stubs + the hook-free CPU MATE buddy ----
// paprium_addons: 32X "MARS" (status[69]) and the Mega CD
// stub (0.2.6: the Mega CD unit list; was status[70] + model [73:71]), on clk_md like the Pocket (md_board's MCLK2). paprium_mcd_link (clk_md):
// post detector, 12.5 MHz not-before timer, honest busy / COMSTAT2 ($A12024). paprium_snoop (clk_sys): Word RAM /
// PRG-RAM / $FF9920 writes into the compact window paprium_xwin (MiSTer equivalent of the Pocket SRAM, clk_sys).
// paprium_xlink (clk_sys): the MCU's register block 0x0A000000. All gated by paprium_active; with Mega CD None
// the stub answers nothing, the link sees no post and the snoop takes nothing.
wire        addon_data_en;
wire [15:0] addon_data;
wire        od_busy;
wire [15:0] od_comstat2;
wire  [7:0] od_g3;
wire  [6:0] od_link_status;

// ---- 0.2.6: console and Mega CD options. paprium_opts decodes Console
// status[84:82] (bit 85 reserved, always 0 from the menu) and Mega CD status[89:86] (menu entry -> unit number, in the
// Pocket menu order) on clk_sys, where status lives, and applies the hardware rules (region per console / combined unit,
// version nibble + TMSS-lite, $1FE4 model bits, no separate CD on a console without expansion port, DISK). The clk_md
// results go through synch_3 like the Pocket core's opt_md_sync; the MCU (clk_sys) takes {MegaWire, model} straight from the flops.
// All are static settings the game reads at boot: change them, then Reset.
reg  [3:0] opt_megacd;
always @(*) begin
	case (status[89:86])                // OSD entry -> unit (paprium_addons table)
		4'd1:    opt_megacd = 4'd2;      // Mega-CD / Sega CD
		4'd2:    opt_megacd = 4'd3;      // Mega-CD 2 / Sega CD 2
		4'd3:    opt_megacd = 4'd4;      // Wondermega
		4'd4:    opt_megacd = 4'd5;      // Wondermega M2 / X'Eye
		4'd5:    opt_megacd = 4'd6;      // LaserActive
		4'd6:    opt_megacd = 4'd1;      // Aiwa CSD-GM1 (= the old Mega CD Mode stub)
		4'd7:    opt_megacd = 4'd7;      // CDX
		4'd8:    opt_megacd = 4'd8;      // Unknown CD
		default: opt_megacd = 4'd0;      // None
	endcase
end

// 0.3.0 pass 2: the "options apply at reset" latch (MCU_INTERFACE CTRL bit 5, cart output paprium_opt_at_reset_en),
// copied from Pocket core_top 752-776. DORMANT: the RELEASE firmware writes 0, so the live OSD values pass straight
// through as in 0.2.6. With 1, console / Mega CD / MegaWire hold the value from the clock before it rose until the
// next reset clears the bit. Option clock here = clk_sys (where status lives).
wire       opt_at_reset_en;             // paprium_cart CTRL[5], clk_sys
wire       opt_at_reset_s;
synch_3 opt_at_reset_sync (.i(opt_at_reset_en), .o(opt_at_reset_s), .clk(clk_sys));
reg  [3:0] opt_console_q = 4'd0;
reg  [3:0] opt_megacd_q  = 4'd0;
reg        opt_mwire_q   = 1'b0;
always @(posedge clk_sys) if (!opt_at_reset_s) begin
	opt_console_q <= status[85:82];
	opt_megacd_q  <= opt_megacd;
	opt_mwire_q   <= status[90];
end
wire [3:0] opt_console_e = opt_at_reset_s ? opt_console_q : status[85:82];
wire [3:0] opt_megacd_e  = opt_at_reset_s ? opt_megacd_q  : opt_megacd;
wire       opt_mwire_e   = opt_at_reset_s ? opt_mwire_q   : status[90];

wire       opt_jap, opt_ver1, opt_disk_n, opt_cd_real, opt_td_en;
wire [3:0] opt_model, opt_cd_unit;
paprium_opts opts
(
	.clk    (clk_sys),
	.console(opt_console_e),            // 0.3.0 F3: 4 bits, 8 = TeraDrive (pass 2: through the CTRL[5] latch)
	.megacd (opt_megacd_e),
	.jap    (opt_jap),
	.ver1   (opt_ver1),
	.model  (opt_model),
	.cd_unit(opt_cd_unit),
	.disk_n (opt_disk_n),
	.cd_real(opt_cd_real),
	.td_en  (opt_td_en)
);

wire       opt_jap_s, opt_ver1_s, opt_disk_n_s, opt_cd_real_s, opt_td_en_s;
wire [3:0] opt_cd_unit_s;
synch_3 #(.WIDTH(9)) opt_md_sync
(
	.i({opt_td_en, opt_jap, opt_ver1, opt_disk_n, opt_cd_real, opt_cd_unit}),
	.o({opt_td_en_s, opt_jap_s, opt_ver1_s, opt_disk_n_s, opt_cd_real_s, opt_cd_unit_s}),
	.clk(clk_md)
);
assign JAP = opt_jap_s;

// buddy enable = a recognised Mega CD unit
wire        cd_mode_on = paprium_active & opt_cd_real_s;
// TMSS-lite: a version-1 console, unless the real TMSS (OSD TMSS + BIOS) is in, which answers those registers itself
wire        tmss_lite_on;                 // assigned after the tmss_enable/tmss_loaded flops (below)
wire        addon_dtack;

paprium_addons addons
(
	.clk         (clk_md),
	.reset       (s_reset),
	.active      (paprium_active),
	.tmss_reset  (md_reset_board_q),   // md_board's ext_reset (SRES) clears the TMSS latch
	.en_32x      (status[69]),
	.cd_unit     (opt_cd_unit_s),
	.tmss_on     (tmss_lite_on),
	.cart_addr   (cart_addr),
	.cart_oe     (cart_oe),
	.cart_lwr    (cart_lwr),
	.cart_uwr    (cart_uwr),
	.cart_data_wr(cart_data_wr),
	.busy        (od_busy),
	.comstat2    (od_comstat2),
	.g3_q        (od_g3),
	.data_en     (addon_data_en),
	.data_out    (addon_data),
	.dtack       (addon_dtack)
);

// MCU external bus (cartridge -> paprium_cart, clk_sys)
wire        xb_req;
wire  [1:0] xb_region;
wire [23:0] xb_addr;
wire  [3:0] xb_sel;
wire        xb_wr;
wire [31:0] xb_wdata;
wire [31:0] xb_rdata;
wire        xb_ack;

wire        xs_ack, xl_ack;
wire [31:0] xs_rdata, xl_rdata;
// 0.3.0: region 1 (MCU 0x09000000-0x093FFFFF, the Pocket's CRAM) is paprium_cram_ddr on the DDR3 port
wire [31:0] xc_rdata, xc_ops;
wire        xc_ack;
assign xb_ack   = (xb_region == 2'd0) ? xs_ack   : (xb_region == 2'd2) ? xl_ack   : (xb_region == 2'd1) ? xc_ack   : 1'b1;
assign xb_rdata = (xb_region == 2'd0) ? xs_rdata : (xb_region == 2'd2) ? xl_rdata : (xb_region == 2'd1) ? xc_rdata : 32'hFFFFFFFF;
// the synth's CRAM ports (paprium_cart PAPRIUM_SYNTH = 1) and the interim echo line (not built with the synth)
wire        echo_ready, echo_wr, echo_rd, echo_rd_done;
wire [12:0] echo_wslot, echo_rslot;
wire [31:0] echo_wdata, echo_rdata;
wire        syn_c_rd, syn_c_rd_done, syn_e_wr, syn_e_wpair, syn_e_rd, syn_e_rpair, syn_e_rd_done, syn_e_wbusy;
wire [20:0] syn_c_raddr;
wire [15:0] syn_c_rdata;
wire [21:0] syn_e_waddr, syn_e_raddr;
wire [31:0] syn_e_wdata, syn_e_rdata;
// XLINK 0.3.0 outputs
wire [31:0] xcfg;
wire        xl_cache_valid;   // LIVE
wire        od_post_bit;
wire        xl_bar_en;
wire [10:0] xl_bar_px;

wire [23:0] xl_d_word, xl_d_busy;
wire [15:0] xl_pend;
wire        xl_arm_tg, xl_od_en;
wire  [3:0] xl_clr_tg;
wire  [7:0] xl_hold;
wire  [3:0] od_flags;
wire        od_armed, od_sres, od_sbrq;
wire  [7:0] od_late;
wire [15:0] od_posts;
wire [23:0] od_tick;
wire        od_en_mirror, od_en_prg;

// option-D state resets with the cartridge (s_reset = the clk_md source of sys_reset), not with md_reset
paprium_mcd_link mcd_link
(
	.clk         (clk_md),
	.reset       (s_reset),
	.en_cd       (cd_mode_on),
	.cart_addr   (cart_addr),
	.cart_lwr    (cart_lwr),
	.cart_data_wr(cart_data_wr),
	.g3_q        (od_g3),
	.d_word      (xl_d_word),
	.d_busy      (xl_d_busy),
	.pend        (xl_pend),
	.arm_tg      (xl_arm_tg),
	.clr_tg      (xl_clr_tg),
	.od_en       (xl_od_en),
	.hold        (xl_hold),
	.busy        (od_busy),
	.comstat2    (od_comstat2),
	.flags       (od_flags),
	.armed       (od_armed),
	.sres_run    (od_sres),
	.sbrq        (od_sbrq),
	.late_count  (od_late),
	.post_count  (od_posts),
	.tick        (od_tick),
	.en_mirror   (od_en_mirror),
	.en_prg      (od_en_prg)
);

// window / snoop / xlink: power-on reset only (PLL lock), as the Pocket's xmem block
reg  [2:0] xmem_lock_s = 3'b000;
reg        xmem_ever = 1'b0;
always @(posedge clk_sys) begin
	xmem_lock_s <= {xmem_lock_s[1:0], pll_locked};
	if (xmem_lock_s[2]) xmem_ever <= 1'b1;
end
wire xmem_reset = ~xmem_ever;

wire  [1:0] sn_en_s;
synch_3 #(.WIDTH(2)) sn_en_sync (.i({od_en_prg, od_en_mirror}), .o(sn_en_s), .clk(clk_sys));

wire        sn_valid, sn_take;
wire [16:0] sn_waddr;
wire [15:0] sn_data;
wire  [1:0] sn_be;
wire [15:0] sn_ovf, sn_prg;
wire [31:0] xs_sn_words;

paprium_snoop snoop
(
	.clk         (clk_sys),
	.reset       (xmem_reset),
	.en_mirror   (sn_en_s[0]),
	.en_prg      (sn_en_s[1]),
	.cart_addr   (cart_addr),
	.cart_lwr    (cart_lwr),
	.cart_uwr    (cart_uwr),
	.cart_data_wr(cart_data_wr),
	.sn_valid    (sn_valid),
	.sn_waddr    (sn_waddr),
	.sn_data     (sn_data),
	.sn_be       (sn_be),
	.sn_take     (sn_take),
	.stat_prg    (sn_prg),
	.stat_overflow(sn_ovf)
);

paprium_xwin xwin
(
	.clk     (clk_sys),
	.reset   (xmem_reset),
	.sn_valid(sn_valid),
	.sn_waddr(sn_waddr),
	.sn_data (sn_data),
	.sn_be   (sn_be),
	.sn_take (sn_take),
	.cfg_lock(xcfg[16]),                // 0.3.0: MegaWire area write lock (XCFG bit 16)
	.mc_req  (xb_req & (xb_region == 2'd0)),
	.mc_addr (xb_addr[17:0]),
	.mc_sel  (xb_sel),
	.mc_wr   (xb_wr),
	.mc_wdata(xb_wdata),
	.mc_rdata(xs_rdata),
	.mc_ack  (xs_ack),
	.stat_snoop_writes(xs_sn_words)
);

paprium_xlink #(.STAGE2(1'b1)) xlink
(
	.clk  (clk_sys),
	.reset(xmem_reset),
	.od_reset(sys_reset),
	.req  (xb_req & (xb_region == 2'd2)),
	.addr (xb_addr[6:0]),
	.wr   (xb_wr),
	.wdata(xb_wdata),
	.rdata(xl_rdata),
	.ack  (xl_ack),
	.xcfg (xcfg),
	.st_snoop      (xs_sn_words),
	.st_loaded     (32'd0),
	.st_cram_ops   (xc_ops),
	.st_underruns  (16'd0),
	.st_snoop_ovf  (sn_ovf),
	.st_snoop_prg  (sn_prg),
	.st_loader_lost(16'd0),
	.st_cram_lost  (16'd0),
	.st_cram_ready (1'b1),
	.d_word(xl_d_word), .d_busy(xl_d_busy), .pend(xl_pend), .arm_toggle(xl_arm_tg),
	.clr_toggle(xl_clr_tg), .od_en(xl_od_en), .od_hold(xl_hold),
	.stub_lstat({od_sbrq, od_sres, od_armed, od_busy, od_flags}),
	.stub_late_count(od_late), .stub_post_count(od_posts), .stub_tick(od_tick),
	.link_status(od_link_status),
	.post_bit(od_post_bit),             // 0.3.0 stage 1 (M2) -> paprium_cart link_post
	// 0.3.0 (MCU interface v1.3 section 3.9): no sound-cache slot on MiSTer (B Jam's answer 4: unpack at every launch),
	// so CACHE_LOADED reads 0 always; BAR drives the hold video / red screen below.
	.cache_valid(xl_cache_valid),       // LIVE: readout only
	.cache_size(),
	.st_cache_loaded(23'd0),
	.bar_en(xl_bar_en),
	.bar_px(xl_bar_px),
	.bar_w(11'd320),                    // BAR.W: the hold picture's active width (H40). Pocket: paprium_bar's width
	.st_fw_len_bad(fw_len_bad)          // XLINK FAFRIUM bit 0 (cartridge.sv, clk_sys)
);

// 0.2.6: the Pocket core's MCU option packing (paprium_cart.sv gpio_i): [18:16] the $1FE6 MegaWire status x3 (7 = plugged and
// signed in, 0 = none), [10:8] and [6] the console's $1FE4 model bits. ppm_reset copies the low half into $1FE4 (with
// busy) and the high half into $1FE6 at every MCU boot.
// 0.3.0 pass 2: Arcade OSD -> Grand Stick III / 4-Way Play settings (used by paprium_pads below and cart stage_sel)
wire [1:0] arcmode     = status[93:92];
wire [1:0] arc_coins   = status[95:94];
wire       arc_attract = status[96];
wire       arc_p3      = status[97];
wire       arc_on12    = (arcmode == 2'd1) | (arcmode == 2'd2);
wire [4:0] arc_stage_a = status[68:64];
wire [4:0] arc_stage_b = 5'd0;          // Pocket splits the stage list in two OSD rows; MiSTer has one list
wire [8:0] gs3_live    = {(arcmode != 2'd0),
                          (arcmode != 2'd0) & ((arcmode == 2'd2) | arc_p3),
                          arc_on12,
                          arc_on12 ? {1'b1, (arc_coins == 2'd2), arc_attract, (arc_coins == 2'd1), 1'b0, (arcmode == 2'd2)} : 6'd0};
wire       tap_live    = arc_p3 & (arcmode == 2'd0);
reg  [8:0] gs3_sys = 9'd0;
reg        tap_sys = 1'b0;
reg  [4:0] arc_stage_sel = 5'd0;
wire [8:0] gs3_sys_nx = sys_reset ? gs3_live : gs3_sys;
wire       tap_sys_nx = sys_reset ? tap_live : tap_sys;
always @(posedge clk_sys) begin
	gs3_sys <= gs3_sys_nx;
	tap_sys <= tap_sys_nx;
	if (sys_reset) arc_stage_sel <= arc_on12 ? ((arc_stage_b != 5'd0) ? arc_stage_b : arc_stage_a) : 5'd0;
end
wire pap_pads_use = gs3_sys[8] | tap_sys;

// 0.3.0 option word: paprium_cart packs mcu_opts[7:0] =
// {PAL build, Console region is Japan, menu open, MegaWire, $1FE4 bit 10, 9, 8, 6} into gpio bits 26, 25, 24, 18-16,
// 10-8, 6. MENU = the OSD is open while "Pause When OSD is Open" is on; PAL = 0 (no PAL build).
reg         osd_pause_sys = 1'b0;
always @(posedge clk_sys) osd_pause_sys <= OSD_STATUS & status[61];
wire  [7:0] mcu_opts = {1'b0, opt_jap, osd_pause_sys, opt_mwire_e, opt_model}; // pass 2: MegaWire via CTRL[5] latch
wire [31:0] mcu_gpio_in = {5'd0, mcu_opts[7:5], 5'd0, {3{mcu_opts[4]}}, 5'd0, mcu_opts[3:1], 1'b0, mcu_opts[0], 6'd0}; // cartridge port kept, unread in 0.3.0

wire [15:0] cart_data    = addon_data_en ? addon_data : mdp_data_en ? mdp_data_out : cart_data_rom;
wire        cart_data_en = addon_data_en | mdp_data_en | cart_data_en_rom;
wire        cart_dtack   = mdp_dtack   | cart_dtack_rom | addon_dtack;   // 0.2.6: + TMSS-lite

wire        board_reset_n; // from md_board RESET (active-low)
wire        board_halt_n;  // from md_board HALT (active-low)

wire        vdp_hclk1;
wire        vdp_de_h;
wire        vdp_de_v;
wire        vdp_intfield;
wire        vdp_m2, vdp_m5, vdp_rs1;
wire  [7:0] r,g,b;
wire        hs, vs;

wire  [6:0] PA_d, PA_o, PB_d, PB_o, PC_d, PC_o;
wire  [6:0] PA_i, PB_i, PC_i;

wire  [8:0] MOL, MOR;
wire  [9:0] MOL_2612, MOR_2612;
wire [15:0] PSG;
wire        fm_clk1;
wire        fm_sel23;

wire [14:0] ram_68k_address;
wire  [1:0] ram_68k_byteena;
wire [15:0] ram_68k_data;
wire        ram_68k_wren;
wire [15:0] ram_68k_o;
wire [12:0] ram_z80_address;
