	// video
	.V_R(r),
	.V_G(g),
	.V_B(b),
	.V_HS(hs),
	.vdp_vsync2(vs),
	
	// audio
	.MOL(MOL),
	.MOR(MOR),
	.MOL_2612(MOL_2612),
	.MOR_2612(MOR_2612),
	.PSG(PSG),
