dpram_difclk #(10,16,10,16) rom_tmss
(
	.clock_a(clk_md),
	.address_a(tmss_address),
	.q_a(tmss_data),

	.clock_b(clk_sys),
	.address_b(ioctl_addr[10:1]),
	.wren_b(ioctl_wr && tmss_download && !ioctl_addr[24:11]),
	.data_b({ioctl_data[7:0],ioctl_data[15:8]})
);

reg tmss_enable = 0;
reg tmss_loaded = 0;
assign tmss_lite_on = opt_ver1_s & ~(tmss_enable & tmss_loaded);   // 0.2.6: TMSS-lite unless the real TMSS is in
always @(posedge clk_sys) begin
	if(ioctl_wr & tmss_download) tmss_loaded <= 1;
	if(sys_reset) tmss_enable <= status[12];
end

// 0.3.0 FPGAIO FEAT, composed as the Pocket's core_top.sv (~318-337): CACHE | BAR | SYNTH | GS3, IROM 88 KB =
// 0x0058_0047 (PLAN section 5.1: MiSTer shows the MCU the Pocket's board; CACHE stays 1, CACHE_LOADED reads 0).
localparam [31:0] PAPRIUM_FEAT = {8'd0, 8'd88, 9'd0, 1'b1, 1'b0, 1'b0, 1'b0, 1'b1, 1'b1, 1'b1};
wire        paprium_menu_mute_en;
wire        menu_mute = osd_pause_sys & paprium_menu_mute_en;   // CTRL bit 4: the cart SFX pair is 0 while the OSD pauses
wire        paprium_vs_tog_s;
paprium_vs_tap paprium_vs_tap (.clk_md(clk_md), .vs_n(vs), .clk_sys(clk_sys), .vs_tog_s(paprium_vs_tog_s));

wire [13:0] sms_fm_audio = 14'd0; // FXSMS1: SMS FM (OPLL) mix input tied to 0; audio_cond.sv unchanged
wire        gun_type;
wire  [7:0] gun_sensor_delay;
wire        ym2612_quirk;

cartridge #(
	.CLK_HZ(53693175),                  // clk_sys
	.CLK_MD_HZ(107386350),              // clk_ram / clk_md
	.PAPRIUM_FEAT(PAPRIUM_FEAT),
	.PAPRIUM_SYNTH(1'b1)
) cartridge
