	.cart_dtack(cart_dtack_rom),
	.cart_dma(cart_dma),

	.save_addr({3'd0,sd_lba[3:0],sd_buff_addr[7:0]}), // pass 2: 8 KB backup = 16 sectors (cart AW=12)
	.save_di(sd_buff_dout),
	.save_do(sd_buff_din),
	.save_wr(sd_buff_wr & sd_ack[0]),
	.save_change(bk_change),

