	.paprium_opt_at_reset_en(opt_at_reset_en), // pass 2: CTRL bit 5 -> option latch (opt_*_q above)
	.paprium_console_reset(1'b0),      // PASS9: Console Reset removed (no CAUSE.V post)
	.paprium_cause_v(),
	.paprium_menu_mute_en(paprium_menu_mute_en),
	.mcu_opts(mcu_opts),
	.link_post(od_post_bit),
