generate
if (ENABLE_MDP_AUDIO) begin : mdp_on
mdp_audio mdp_audio
(
	.clk(clk_sys),
	.reset(sys_reset | paprium_active),

	.DDRAM_CLK(),
	.DDRAM_BUSY(DDRAM_BUSY),
