// 0.3.0: the album stack (FS3 paprium.pcm loader, SD slot-1 fetch,
// cdda buf / IMA / play) is removed; the cart's own music is the synth on paprium_sfx_l / r. The DDR3 port it left idle
// now carries the MCU's CRAM window (region 0x09, 4 MB) and the synth's ports C / E: paprium_cram_ddr below.
assign pcm_cdda_l = 16'sd0;
assign pcm_cdda_r = 16'sd0;
assign mdp_pcm_playing = 1'b0;
assign mdp_pcm_current_track = 8'd0;

// PASS9: the DDRFLAGS / LIVE OSD readout block (ddr_flags, ddr_rost, rst_dbg, dbg_val pages, Heartbeat, ddr_set) is removed.
// PASS9: that block (xl_woff, the cram0 write count) was the only reader of the MCU bus address bits [1:0]. With no reader,
// Quartus 21.1 map stops with Internal Error OPT opt_arm_carry.cpp:500 (!sutil_op_has_some_fanout (adder)) on the NEORV32
// address adder feeding mcu_core's keep'd rv_ad[1:0]. This 2-bit register keeps one reader on those bits. It drives nothing.
(* noprune *) reg [1:0] mcu_ad_lo_sink = 2'd0;
always @(posedge clk_sys) mcu_ad_lo_sink <= xb_addr[1:0];
assign DDRAM_CLK = clk_sys;
paprium_cram_ddr #(.BASE_QW(29'h0700_0000)) cram_ddr   // DDR3 byte 0x3800_0000 (the old album blob base, out of Linux RAM)
(
	.clk      (clk_sys),
	.reset    (xmem_reset),
	.fw_done  (fw_done),
	.b_req    (xb_req & (xb_region == 2'd1)),
	.b_addr   (xb_addr[21:0]),
	.b_sel    (xb_sel),
	.b_wr     (xb_wr),
	.b_wdata  (xb_wdata),
	.b_rdata  (xc_rdata),
	.b_ack    (xc_ack),
	.c_rd     (syn_c_rd),
	.c_raddr  (syn_c_raddr),
	.c_rd_done(syn_c_rd_done),
	.c_rdata  (syn_c_rdata),
	.e_wr     (syn_e_wr),
	.e_waddr  (syn_e_waddr),
	.e_wpair  (syn_e_wpair),
	.e_wdata  (syn_e_wdata),
	.e_rd     (syn_e_rd),
	.e_raddr  (syn_e_raddr),
	.e_rpair  (syn_e_rpair),
	.e_rd_done(syn_e_rd_done),
	.e_rdata  (syn_e_rdata),
	.e_wbusy  (syn_e_wbusy),
	.DDRAM_BUSY      (DDRAM_BUSY),
	.DDRAM_BURSTCNT  (DDRAM_BURSTCNT),
	.DDRAM_ADDR      (DDRAM_ADDR),
	.DDRAM_DOUT      (DDRAM_DOUT),
	.DDRAM_DOUT_READY(DDRAM_DOUT_READY),
	.DDRAM_RD        (DDRAM_RD),
	.DDRAM_DIN       (DDRAM_DIN),
	.DDRAM_BE        (DDRAM_BE),
	.DDRAM_WE        (DDRAM_WE),
	.stat_ops        (xc_ops),
	.stat_bage       ()                // PASS9: was the DDR flags 'slow' readout only
);
// PAPRIUM_SYNTH = 1: echo_* (audio_sfx's line) is not built in paprium_cart; answer it idle.
assign echo_ready   = 1'b1;
assign echo_rd_done = 1'b0;
assign echo_rdata   = 32'd0;


