// 0.3.0 hold video. While XLINK BAR.EN is set (first start: the
// stub, the sound-bank unpack) the picture is held black; BAR.EN with BAR.PX = 2047 is the stub's refusal: every
// active dot (255, 0, 0), no text, no OSD info line, no sound (AUDIO muted below; the 68000 and the synth idle). The
// core's own syncs / blanks are kept (video_cond / VDP keep running), so HDMI and analog keep a locked picture.
// The Pocket's progress bar drawing is not ported: during the unpack MiSTer shows black without the bar.
wire [11:0] bar_vid;
synch_3 #(.WIDTH(12)) bar_sync (.i({xl_bar_en, xl_bar_px}), .o(bar_vid), .clk(CLK_VIDEO));
wire        hold_vid = bar_vid[11];
wire        hold_red = bar_vid[11] & (&bar_vid[10:0]);

video_mixer #(.LINE_LENGTH(400), .GAMMA(1)) video_mixer
(
	.*,

	.scandoubler(~interlace && (scale || forced_scandoubler)),
	.hq2x(scale==1),
	.freeze_sync(),

	.VGA_DE(vga_de),
	.R(hold_vid ? {8{hold_red}} : (lg_target && gun_mode && (~&status[44:43])) ? {8{lg_target[0]}} : r_c),
	.G(hold_vid ? 8'd0          : (lg_target && gun_mode && (~&status[44:43])) ? {8{lg_target[1]}} : g_c),
	.B(hold_vid ? 8'd0          : (lg_target && gun_mode && (~&status[44:43])) ? {8{lg_target[2]}} : b_c),

	// Positive pulses.
	.HSync(hs_c),
	.VSync(vs_c),
	.HBlank(hblank_c),
	.VBlank(vblank_c)
);

